import { IMessageChannelOptions } from '../types';
import { NativeMessageChannel } from './native';
import { WebMessageChannel } from './web';

export * from './base';

export class MessageChannelFactory {
    public static create(options: IMessageChannelOptions) {
        switch (options.type) {
            case 'web':
                return new WebMessageChannel(options);
            case 'native':
                return new NativeMessageChannel(options);
        }
    }
}